from collections.abc import Iterable, Mapping

COUNTERS = ("input_tokens", "output_tokens", "settled_cents")
FIELDS = {"id", *COUNTERS}


def aggregate_usage(records: Iterable[Mapping[str, object]]) -> dict[str, int | None]:
    unique: dict[str, tuple[int | None, int | None, int | None]] = {}
    for record in records:
        if set(record) != FIELDS:
            raise ValueError("invalid usage record")
        identity = record["id"]
        if not isinstance(identity, str) or not identity.strip():
            raise ValueError("invalid usage record")
        identity = identity.strip()
        values = tuple(record[field] for field in COUNTERS)
        if any(value is not None and (type(value) is not int or value < 0)
               for value in values):
            raise ValueError("invalid usage record")
        normalized = values
        if identity in unique and unique[identity] != normalized:
            raise ValueError(f"conflicting usage record: {identity}")
        unique[identity] = normalized  # type: ignore[assignment]

    totals: dict[str, int | None] = {}
    for index, field in enumerate(COUNTERS):
        values = [record[index] for record in unique.values()]
        totals[field] = sum(values) if all(value is not None for value in values) else None
    return {"calls": len(unique), **totals}
